class TaskBinding {static Object vehicle(int p,int f,int m){return new alternate.Vehicle(p,f,m);}static int[] state(Object x){alternate.IVehicle v=(alternate.IVehicle)x;return new int[]{v.getPassengers(),v.getFuelcap(),v.getMpg()};}static int range(Object x){return ((alternate.IVehicle)x).range();}static double fuel(Object x,int miles){return ((alternate.IVehicle)x).fuelNeeded(miles);}static void set(Object x,int field,int value){alternate.IVehicle v=(alternate.IVehicle)x;switch(field){case 0->v.setPassengers(value);case 1->v.setFuelcap(value);case 2->v.setMpg(value);}}}
